vec2 warp(vec2 uv) {
    float x = uv.x;
    float y = uv.y;

    x += cos(iTime*.2);
    y += sin(iTime*.2);
    x = (x*.6+.2)*2.;
    y = y*2.;
    return vec2(x*7. + cos((x+5.)*(y*.5-3.)*3.), y*3. + sin((x*.8+.3)*(y*.6+2.)*4.) + sin((x*.2+.3)*(y*.3+2.)*3.));
}

float getHeight(vec2 uv) {
    float c = (cos(3.*cos(uv.x) + 5.*sin(uv.y)) + 1.) / 2.;
    if (c < .95)
        return 0.;
    return (c-.95) * 20.;
}

vec2 getGradient(vec2 uv) {
    float d = .1;
    float h_x1 = getHeight(uv + vec2(-d, 0.));
    float h_x2 = getHeight(uv + vec2(d, 0.));
    float h_y1 = getHeight(uv + vec2(0., d));
    float h_y2 = getHeight(uv + vec2(0., -d));
    vec2 g = vec2(
        (h_x2-h_x1) / (2.*d),
        (h_y2-h_y1) / (2.*d)
    );

    float l = length(g);
    return l == 0. ? g : g / l;
}

vec3 getCol(vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 uv_w = warp(uv);

    vec2 gradient = getGradient(uv_w);

    vec3 col1 = vec3(137., 201., 255.) / 255.;
    vec3 col2 = vec3(243., 149., 109.) / 255.;
    vec3 col3 = vec3(73., 111., 151.) / 255.;
    vec3 back_col = col1 + (col2-col1) * uv.x;
    back_col += (col3-back_col) * (1.-uv.y);

    float light = (gradient.x+gradient.y+4.) / 6. + .4;
    return back_col * light;
}

vec4 aalias(vec2 fragCoord, int count) {
    vec3 acc = vec3(0., 0., 0.);

    for (int x = 0; x < count; x++)
    for (int y = 0; y < count; y++)
        acc += getCol(fragCoord + vec2(float(x) / float(count), float(y) / float(count)));

    return vec4(acc / float(count * count), 1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = aalias(fragCoord, 4);
}
